import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Install and upgrade","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/install.md","filePath":"troubleshooting/install.md","lastUpdated":1793232148000}'),i={name:"troubleshooting/install.md"};function n(l,e,r,p,d,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="install-and-upgrade" tabindex="-1">Install and upgrade <a class="header-anchor" href="#install-and-upgrade" aria-label="Permalink to &quot;Install and upgrade&quot;">​</a></h1><p>This page helps when Scoop can&#39;t install or update MeetCue, when Windows blocks it, or when settings seem lost after an update.</p><h2 id="download" tabindex="-1">Scoop can&#39;t download MeetCue <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Scoop can&#39;t download MeetCue {#download}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>No internet access to <code>github.com</code>, or a proxy is required.</li><li>The bucket was added with a wrong address.</li></ol><p><strong>Check</strong></p><ol><li>Run <code>scoop bucket list</code> and check the address of the <code>meetcue</code> bucket.</li><li>Open <code>https://github.com/Amazingkenneth/meetcue/releases</code> in a browser.</li></ol><p><strong>Fix</strong></p><ol><li><p>Re-add the bucket:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket rm meetcue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket add meetcue https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Amazingkenneth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meetcue</span></span></code></pre></div></li><li><p>Behind a proxy, configure Scoop with <code>scoop config proxy proxy.example.com:8080</code>.</p></li></ol><p><strong>Still not solved?</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">Open an issue</a> with the full Scoop output.</p><h2 id="hash" tabindex="-1">Scoop reports a hash mismatch <a class="header-anchor" href="#hash" aria-label="Permalink to &quot;Scoop reports a hash mismatch {#hash}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>A download was interrupted or altered by a proxy.</li><li>Your local bucket is out of date.</li></ol><p><strong>Check</strong></p><ol><li>Run <code>scoop update</code> to refresh all buckets.</li></ol><p><strong>Fix</strong></p><ol><li><p>Clear the cached download and try again:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop cache rm meetcue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop install meetcue</span></span></code></pre></div></li></ol><p><strong>Still not solved?</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">Open an issue</a> with the full Scoop output.</p><h2 id="blocked" tabindex="-1">Windows or antivirus blocks MeetCue <a class="header-anchor" href="#blocked" aria-label="Permalink to &quot;Windows or antivirus blocks MeetCue {#blocked}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>MeetCue isn&#39;t code-signed in this release, so SmartScreen may warn about an unknown publisher.</li><li>Antivirus software flags a new, rarely downloaded program.</li><li>Company policy only allows approved programs.</li></ol><p><strong>Check</strong></p><ol><li>Note the exact message and which program shows it.</li></ol><p><strong>Fix</strong></p><ol><li>For SmartScreen, click <strong>More info › Run anyway</strong> if you trust the download. The release page lists the SHA-256 hash of the zip so you can compare it.</li><li>Report a false positive to your antivirus vendor, or ask IT to allow <code>MeetCue.exe</code>.</li><li>If company policy blocks unsigned programs, MeetCue can&#39;t run there until signed builds are available.</li></ol><p><strong>Still not solved?</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">Open an issue</a>.</p><h2 id="webview2" tabindex="-1">MeetCue reports that WebView2 is missing <a class="header-anchor" href="#webview2" aria-label="Permalink to &quot;MeetCue reports that WebView2 is missing {#webview2}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The Microsoft Edge WebView2 runtime was removed or never installed (<a href="/meetcue/troubleshooting/error-codes#mc-sys-001">MC-SYS-001</a>).</li></ol><p><strong>Check</strong></p><ol><li>Look for <strong>Microsoft Edge WebView2 Runtime</strong> in <strong>Settings › Apps › Installed apps</strong>.</li></ol><p><strong>Fix</strong></p><ol><li>Download and install the Evergreen WebView2 runtime from Microsoft, then start MeetCue again.</li></ol><p><strong>Still not solved?</strong> <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">Open an issue</a>.</p><h2 id="settings-lost" tabindex="-1">Settings are gone after an update <a class="header-anchor" href="#settings-lost" aria-label="Permalink to &quot;Settings are gone after an update {#settings-lost}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>MeetCue couldn&#39;t write to its folder and saved settings in <code>%APPDATA%\\MeetCue</code> instead (<a href="/meetcue/troubleshooting/error-codes#mc-sys-002">MC-SYS-002</a>).</li><li>MeetCue was uninstalled with <code>--purge</code>.</li></ol><p><strong>Check</strong></p><ol><li>Open <strong>Settings › Diagnostics › About</strong> and look at <strong>Settings folder</strong>. With Scoop it should be under <code>scoop\\persist\\meetcue\\config</code>.</li></ol><p><strong>Fix</strong></p><ol><li>If the settings are in <code>%APPDATA%\\MeetCue</code>, copy <code>settings.json</code> and <code>latency-history.json</code> into the persist folder, then restart MeetCue.</li><li>API keys stay in Windows Credential Manager and survive updates and uninstalls.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p>`,42)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
